@startuml

class Customer {
  + name : string
  + phone_number : string
}

class Table {
  + number_of_seats : int
  + is_smoking : boolean
}

class Reservation {
  + day : date
  + time : time
  + number_of_people : int
}

class Waiter {
  + name : string
  + years_of_service : int
}

class Bill {
  + total_amount : double
}

class Dish {
  + name : string
  + unit_price : double
}

class BillItem {
  + quantity : int
}

Customer "1" -- "*" Reservation : makes
Reservation "*" -- "0..1" Table : is assigned to
Waiter "1" -- "*" Table : serves
Customer "1" -- "*" Table : sits at
Bill "1" -- "*" BillItem : contains
Dish "1" -- "*" BillItem : is in
Bill "1" -- "1" Table : for

@enduml

